css=b'/* Compact, locally hosted brand links. */\n.footer-socials { grid-column:1 / -1; display:flex; flex-wrap:wrap; align-items:center; gap:8px; border-top:1px solid var(--line); padding-top:8px; }\n.footer-socials a { position:relative; display:grid; place-items:center; width:44px; height:44px; border-radius:50%; background:transparent; transition:background-color .18s ease; }\n.footer-socials img { width:24px; height:24px; opacity:.78; transition:transform .22s cubic-bezier(.16,1,.3,1),opacity .18s; }\n.footer-socials a:hover,.footer-socials a:focus-visible { background:#29283d; }\n.footer-socials a:hover img,.footer-socials a:focus-visible img { opacity:1; transform:translateY(-2px); }\n.footer-socials a:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }\n.footer-socials a>span { position:absolute; bottom:calc(100% + 8px); left:50%; transform:translateX(-50%); padding:5px 9px; background:#29283d; color:var(--ink); font-size:12px; white-space:nowrap; opacity:0; pointer-events:none; transition:opacity .12s; border-radius:4px; }\n.footer-socials a:hover>span,.footer-socials a:focus-visible>span { opacity:1; }\n@media(max-width:650px) { .footer-socials { display:grid; grid-template-columns:repeat(5,44px); justify-content:space-between; gap:4px 8px; } .footer-socials a { height:60px; display:flex; flex-direction:column; gap:5px; } .footer-socials a>span { position:static; display:block; transform:none; padding:0; background:transparent; opacity:1; font-size:10px; line-height:1.4; } }\n@media(prefers-reduced-motion:reduce) { .footer-socials img { transition:opacity .12s; } .footer-socials a:hover img,.footer-socials a:focus-visible img { transform:none; } }\n\n/* Two aligned rows: identity/contact, then page/social destinations. */\n.site-footer { grid-template-columns:minmax(120px,.65fr) minmax(0,2fr); align-items:center; gap:16px 56px; padding-block:20px 12px; }\n.site-footer .footer-brand { display:inline-flex; flex-direction:column; gap:6px; font-size:22px; margin:0; width:auto; }\n.site-footer .footer-brand span { font-size:9px; line-height:1.5; letter-spacing:.1em; }\n.site-footer .footer-contacts { grid-template-columns:minmax(0,1.25fr) minmax(0,1fr) 64px; gap:32px; align-items:start; }\n.site-footer .footer-contact-method>p { font-size:12px; margin-bottom:8px; }\n.site-footer .footer-contact-method a { font-size:15px; min-height:30px; }\n.site-footer .footer-wechat img { width:64px; height:64px; }\n.site-footer .footer-bottom { grid-column:1 / -1; display:flex; align-items:center; justify-content:space-between; gap:24px; border-top:1px solid var(--line); padding-top:8px; }\n.site-footer .footer-links { border:0; padding:0; gap:26px; font-size:13px; flex-shrink:0; }\n.site-footer .footer-links a { display:inline-flex; align-items:center; min-height:44px; }\n.site-footer .footer-socials { border:0; padding:0; gap:4px; }\n.site-footer .footer-socials img { width:22px; height:22px; }\n@media(max-width:850px) {\n .site-footer { grid-template-columns:100px minmax(0,1fr); gap:16px 24px; }\n .site-footer .footer-contacts { grid-template-columns:minmax(0,1.2fr) minmax(0,1fr) 64px; gap:16px; }\n .site-footer .footer-contact-method a { font-size:13px; }\n .site-footer .footer-bottom { gap:16px; }\n .site-footer .footer-socials { gap:0; }\n .site-footer .footer-links { gap:16px; }\n}\n@media(max-width:650px) {\n .site-footer { grid-template-columns:1fr; gap:16px; padding-block:18px 12px; }\n .site-footer .footer-brand { font-size:18px; gap:3px; }\n .site-footer .footer-contacts { grid-template-columns:minmax(0,1fr) 64px; gap:6px 16px; }\n .site-footer .footer-contact-method:not(.footer-wechat)>p { margin:0; font-size:11px; }\n .site-footer .footer-contact-method:not(.footer-wechat) a { font-size:12px; min-height:28px; }\n .site-footer .footer-bottom { flex-direction:column; align-items:stretch; gap:8px; padding-top:4px; }\n .site-footer .footer-links { justify-content:space-between; }\n .site-footer .footer-socials { gap:6px 8px; }\n .site-footer .footer-socials a { height:52px; }\n .site-footer .footer-socials a>span { font-size:10px; }\n}\n\n@media(max-width:650px) {\n .site-footer { grid-template-columns:100px minmax(0,1fr); }\n .site-footer .footer-compact-copy { grid-column:1; grid-row:1; }\n .site-footer .footer-contacts { grid-column:1 / -1; grid-row:2; }\n .site-footer .footer-bottom { display:contents; }\n .site-footer .footer-links { grid-column:2; grid-row:1; justify-content:flex-end; align-self:center; gap:16px; font-size:12px; }\n .site-footer .footer-socials { grid-column:1 / -1; grid-row:3; border-top:1px solid var(--line); padding-top:10px; }\n}\n\n/* A QR code must remain large enough to scan, even in the compact footer. */\n.site-footer .footer-contacts { grid-template-columns:minmax(0,1.25fr) minmax(0,1fr) 176px; }\n.site-footer .footer-wechat { grid-column:3; grid-row:1; }\n.site-footer .footer-wechat img { width:176px; height:176px; display:block; }\n.site-footer .footer-wechat a { min-height:176px; }\n@media(max-width:850px) {\n .site-footer .footer-contacts { grid-template-columns:minmax(0,1fr) 176px; }\n .site-footer .footer-wechat { grid-column:2; grid-row:1 / 3; }\n}\n@media(max-width:650px) {\n .site-footer .footer-contacts { grid-template-columns:minmax(0,1fr); gap:12px; }\n .site-footer .footer-wechat { grid-column:1; grid-row:auto; justify-self:start; }\n .site-footer .footer-wechat>p { margin-bottom:8px; }\n}\n'
